-- MIGRASI CASH MARET 2026 - LANGSUNG BERISI DATA FINAL
-- Target: PostgreSQL Prisma schema final Clicco Finance
-- CashTransaction: 1071 rows
-- DebtMutation: 0 rows
-- Total INCOME: 933058071
-- Total EXPENSE: 933196557
-- NET CASH: -138486
-- Laporan laba rugi final - Pendapatan: 903058071, Beban: 834769712, Laba: 68288359

BEGIN;


-- Bersihkan data migrasi Maret yang sama supaya aman dijalankan ulang
DELETE FROM "CashTransaction" WHERE description LIKE '[MIGRASI CASH MAR 2026]%';

-- VALIDASI MASTER DATA WAJIB ADA
-- Rekening yang dipakai: BCA, BRI, BRI CV, CASH, DANA, JENIUS, MANDIRI, MANDIRI CV, OVO, SHOPEE
-- Kategori yang dipakai: BEBAN BONUS KARYAWAN, BEBAN GAPOK, BEBAN LAIN, DEVIDEN (SHARE PROFIT), HPP, IKLAN, PENAMBAHAN MODAL, PENARIKAN MODAL, PENDAPATAN CUST TF, PENDAPATAN LAIN, PENDAPATAN PENCAIRAN BAC, PENDAPATAN PENCAIRAN EVERPRO, PENDAPATAN SHOPEE, PENDAPATAN TIK TOK SHOP
-- Subkategori yang dipakai: ASURANSI DAN BPJS, ATK, BIAYA ADMIN, BIAYA AIR, BIAYA KOMUNIKASI, BIAYA LAINYA, BIAYA LISTRIK, BIAYA PACKING, BIAYA SEWA, BIAYA WIFI, BONUS BOLA TERAPI, BONUS EARCLEANER, BONUS EARPLUG, BUKU, DANA DARURAT, HOSTINGER, INVENTARIS KANTOR, ITEM BONUS ALAT PIJAT, LANGGANAN SOFTWARE, MARKET PLACE, MATERAI, MEETING/INTERTIMENT, ONGKIR PAKET, PAJAK, PERJALANAN DINAS, REFUND DANA, THR, ZAKAT

-- INSERT CASH TRANSACTION

-- CEK HASIL SETELAH INSERT
SELECT type, COUNT(*) AS total_rows, SUM(amount) AS total_amount FROM "CashTransaction" WHERE description LIKE '[MIGRASI CASH MAR 2026]%' GROUP BY type ORDER BY type;
SELECT COUNT(*) AS total_rows, SUM(CASE WHEN type = 'INCOME' THEN amount ELSE 0 END) AS income_total, SUM(CASE WHEN type = 'EXPENSE' THEN amount ELSE 0 END) AS expense_total, SUM(CASE WHEN type = 'INCOME' THEN amount ELSE -amount END) AS net_cash FROM "CashTransaction" WHERE description LIKE '[MIGRASI CASH MAR 2026]%';
SELECT SUM(CASE WHEN ct.type = 'INCOME' AND category.name NOT IN ('PENAMBAHAN MODAL','MODAL AWAL') THEN amount ELSE 0 END) AS pendapatan_lr, SUM(CASE WHEN ct.type = 'EXPENSE' AND category.name NOT IN ('PENARIKAN MODAL','DEVIDEN (SHARE PROFIT)','PENGELUARAN HUTANG','PENGELUARAN PIUTANG') THEN amount ELSE 0 END) AS beban_lr FROM "CashTransaction" ct JOIN "Category" category ON category.id = ct."categoryId" WHERE ct.description LIKE '[MIGRASI CASH MAR 2026]%';

COMMIT;
